"""Wave 22: narrow reviews of ten large fortunes; evidence is mostly thin or runs in the state-to-firm direction. No rubrics added."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
P={};R={}
def r(text,source,url,date,kind='Reported evidence',access='Page text reviewed'):
 return dict(text=text,source=source,url=url,date=date,kind=kind,access=access)
WIKI='Page text read through a fetch summary; encyclopedic secondary source, its own citations not independently opened'
def add(id,summary,mechanism,period,support,counter,limitations,status='no-strong',confidence='Low / narrow review'):
 P[id]=dict(status=status,reviewedAt='2026-10-29',reviewDepth='Narrow source-led review; not independently editorially reviewed',confidence=confidence,period=period,summary=summary,mechanism=mechanism,support=support,counter=counter,limitations=limitations)
